// BALANCE TRANSFER ANALYSIS — and the sentence the marketing never contains:
//
//   A BALANCE TRANSFER DOES NOT REDUCE DEBT. It moves it, and it charges you for the move.
//
// The instant it completes you owe MORE than you did — the balance plus the fee — and net worth has
// gone down by exactly the fee. Everything good about it is a bet that the interest avoided over the
// promotional window will exceed that fee, and that bet is only won by paying the balance down
// during the window. This module prices the bet honestly, including the ways it is lost:
//
//   THE FEE IS ADDED TO THE BALANCE. Transfer $5,000 at 3% and you owe $5,150 on day one.
//   THE GO-TO RATE CAN BE WORSE. Escaping 24.99% into a 0% promo that reverts to 29.99% is a loss
//     unless the balance is gone by then, and "unless" is doing a great deal of work.
//   THE SAVING IS AGAINST WHAT YOU WOULD ACTUALLY PAY, not against the balance sitting still. If you
//     would have cleared it in five months anyway, a twelve-month promotion saves almost nothing and
//     the fee is simply a cost.
//   THE LIMIT CAPS IT, and filling a new card to its limit has a price of its own that is not
//     interest.
import { type Money, money, scale } from "@/features/finance/lib/money";
import type { AccountPosition } from "@/features/finance/lib/position";

export interface TransferOffer {
  readonly id: string;
  readonly institution: string;
  /** Usually 0. A fraction: 0.0499 for 4.99%. */
  readonly promoApr: number;
  readonly promoMonths: number;
  /** A fraction of the transferred amount: 0.03 for 3%. */
  readonly transferFeeRate: number;
  /** Some offers charge a floor regardless of size. */
  readonly transferFeeMin?: Money;
  /** The rate the REMAINING balance reverts to. The number the offer prints smallest. */
  readonly goToApr: number;
  /** Caps what can move. Absent means unknown, not unlimited. */
  readonly creditLimit?: Money;
  readonly offerExpires?: string;
}

export interface TransferAssessment {
  readonly offerId: string;
  readonly institution: string;
  readonly sourceAccount: string;
  /** What actually moves, after the limit caps it. */
  readonly moved: Money;
  /** POSITIVE. Added to the transferred balance, not taken off it. */
  readonly fee: Money;
  /** What you owe on the new card the moment it lands: moved + fee. */
  readonly openingBalance: Money;
  /** Interest you would have paid on the source over the promo window, at the same payment. */
  readonly interestWithout: Money;
  /** Interest you pay having transferred, over the same window. */
  readonly interestWith: Money;
  /** interestWithout − interestWith. Before the fee. */
  readonly interestAvoided: Money;
  /** interestAvoided − fee. NEGATIVE when the move costs more than it saves. */
  readonly netBenefit: Money;
  readonly worthIt: boolean;
  /** What is still owed when the promotional rate ends. Zero is the only comfortable answer. */
  readonly balanceAtPromoEnd: Money;
  /** A year of the go-to rate on whatever is left. The cost of not finishing. */
  readonly costOfNotFinishing: Money;
  /** The monthly payment that clears the whole thing inside the window. */
  readonly requiredMonthly: Money;
  readonly warnings: readonly string[];
}

/**
 * Simple monthly accrual: interest on the balance, then the payment. Deliberately the same model
 * `payoff` uses, so a transfer assessment and a payoff schedule cannot disagree about the same debt.
 */
export function accrue(
  balanceMinor: number,
  apr: number,
  paymentMinor: number,
  months: number,
): { interest: number; balance: number } {
  let b = balanceMinor;
  let interest = 0;
  for (let i = 0; i < months && b > 0; i++) {
    const charge = Math.round(b * (apr / 12));
    interest += charge;
    b = Math.max(0, b + charge - paymentMinor);
  }
  return { interest, balance: b };
}

export interface TransferOptions {
  /** What you will actually put against this debt each month — the SAME on both sides of the
   *  comparison, because otherwise the answer measures a change of behaviour, not the offer. */
  readonly monthlyPayment: Money;
  /** How much to move. Defaults to the whole source balance, capped by the offer's limit. */
  readonly amount?: Money;
  /** Utilisation above which filling the new line is called out. */
  readonly utilisationConcern?: number;
}

export function assessTransfer(
  source: AccountPosition,
  offer: TransferOffer,
  opts: TransferOptions,
): TransferAssessment {
  const currency = source.balance.currency;
  const { monthlyPayment, utilisationConcern = 0.7 } = opts;
  const warnings: string[] = [];

  const owed = source.owed?.minor ?? 0;
  const wanted = opts.amount?.minor ?? owed;
  let moved = Math.max(0, Math.min(wanted, owed));

  if (offer.creditLimit && moved > offer.creditLimit.minor) {
    warnings.push(
      `only ${offer.creditLimit.minor} of ${moved} minor units fits inside ${offer.institution}'s limit — the rest stays where it is, at its own rate, and the plan has to cover both`,
    );
    moved = offer.creditLimit.minor;
  }
  if (!offer.creditLimit) {
    warnings.push(`${offer.institution}'s limit is unknown, so the whole balance is assumed to fit — an assumption, not a fact`);
  }

  const feeMinor = Math.max(Math.round(moved * offer.transferFeeRate), offer.transferFeeMin?.minor ?? 0);
  // THE FEE IS ADDED. You transfer $5,000 at 3% and owe $5,150 the moment it lands.
  const opening = moved + feeMinor;

  const without = accrue(owed, source.apr ?? 0, monthlyPayment.minor, offer.promoMonths);
  const withT = accrue(opening, offer.promoApr, monthlyPayment.minor, offer.promoMonths);
  const avoided = without.interest - withT.interest;
  const net = avoided - feeMinor;

  if (source.apr === undefined) {
    warnings.push(
      `${source.institution}'s rate is unknown, so the interest avoided is computed at 0% — the saving below is a FLOOR and the real one is larger`,
    );
  }
  if (offer.goToApr > (source.apr ?? 0)) {
    warnings.push(
      `the go-to rate of ${Math.round(offer.goToApr * 10000) / 100}% is HIGHER than the ${Math.round((source.apr ?? 0) * 10000) / 100}% you are leaving — anything still owed when the promotion ends costs more than it does today`,
    );
  }
  if (withT.balance > 0) {
    warnings.push(
      `at ${monthlyPayment.minor} a month, ${withT.balance} minor units are still owed when the promotion ends — the whole balance begins accruing at ${Math.round(offer.goToApr * 10000) / 100}% at once, not gradually`,
    );
  }
  if (monthlyPayment.minor <= Math.round(opening * (offer.promoApr / 12))) {
    warnings.push("the payment does not cover even the promotional interest, so the balance grows — this is not a plan, it is a delay");
  }
  if (offer.creditLimit && offer.creditLimit.minor > 0) {
    const utilisation = opening / offer.creditLimit.minor;
    if (utilisation >= utilisationConcern) {
      warnings.push(
        `this fills ${Math.round(utilisation * 100)}% of the new line — a near-full card costs you on a credit score, which is a real price that is not interest`,
      );
    }
  }
  if (net <= 0) {
    warnings.push(
      `the fee of ${feeMinor} is not covered by the ${avoided} of interest it avoids over ${offer.promoMonths} month(s) — on these numbers the move loses money`,
    );
  }

  return {
    offerId: offer.id,
    institution: offer.institution,
    sourceAccount: source.account,
    moved: money(moved, currency),
    fee: money(feeMinor, currency),
    openingBalance: money(opening, currency),
    interestWithout: money(without.interest, currency),
    interestWith: money(withT.interest, currency),
    interestAvoided: money(avoided, currency),
    netBenefit: money(net, currency),
    worthIt: net > 0,
    balanceAtPromoEnd: money(withT.balance, currency),
    costOfNotFinishing: money(Math.round(withT.balance * offer.goToApr), currency),
    // Ceil, because a payment that is a cent short leaves a balance to revert.
    requiredMonthly: money(offer.promoMonths > 0 ? Math.ceil(opening / offer.promoMonths) : opening, currency),
    warnings,
  };
}

/**
 * THE FACT THE MARKETING OMITS: net worth falls by exactly the fee, on day one.
 *
 * It is not a saving, it is a purchase — you are buying a lower rate for a window, and the price is
 * charged whether or not you use the window well.
 */
export const debtAfterTransfer = (source: AccountPosition, a: TransferAssessment): Money =>
  money((source.owed?.minor ?? 0) + a.fee.minor, source.balance.currency);

/** Every offer against every debt, best net benefit first. Losers are KEPT, so a bad offer is
 *  visibly bad rather than absent. */
export function rankTransfers(
  debts: readonly AccountPosition[],
  offers: readonly TransferOffer[],
  opts: TransferOptions,
): TransferAssessment[] {
  const out: TransferAssessment[] = [];
  for (const d of debts) {
    if (!d.owed) continue;
    for (const o of offers) {
      // Moving a balance onto the card it is already on is not a transfer.
      if (o.institution === d.institution) continue;
      out.push(assessTransfer(d, o, opts));
    }
  }
  return out.sort((a, b) => b.netBenefit.minor - a.netBenefit.minor);
}

/** A year of the go-to rate on the whole opening balance — what the offer costs if nothing is paid. */
export const worstCaseAnnual = (a: TransferAssessment, offer: TransferOffer): Money =>
  scale(a.openingBalance, offer.goToApr);

