import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { AccountPosition } from "@/features/finance/lib/position";
import {
  type TransferOffer,
  accrue,
  assessTransfer,
  debtAfterTransfer,
  rankTransfers,
  worstCaseAnnual,
} from "@/features/finance/lib/transfer";

// SYNTHETIC FIXTURES ONLY. No real statement, balance, offer or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const source = (over: Partial<AccountPosition> = {}): AccountPosition => ({
  account: "a",
  institution: "Alpha Card",
  kind: "credit",
  balance: usd(-5000),
  asOf: "2026-06-30",
  rolledForward: 0,
  isDebt: true,
  owed: usd(5000),
  apr: 0.2499,
  minimumPayment: usd(120),
  ...over,
});

const offer = (over: Partial<TransferOffer> = {}): TransferOffer => ({
  id: "omega-0-18",
  institution: "Omega Bank",
  promoApr: 0,
  promoMonths: 18,
  transferFeeRate: 0.03,
  goToApr: 0.2299,
  creditLimit: usd(8000),
  ...over,
});

describe("accrue — the same model payoff uses", () => {
  it("charges interest and then takes the payment", () => {
    const r = accrue(usd(1000).minor, 0.12, usd(100).minor, 1);
    expect(r.interest).toBe(usd(10).minor);
    expect(r.balance).toBe(usd(910).minor);
  });

  it("charges nothing at 0%", () => {
    expect(accrue(usd(1000).minor, 0, usd(100).minor, 3)).toEqual({ interest: 0, balance: usd(700).minor });
  });

  it("stops once the balance is gone rather than going negative", () => {
    expect(accrue(usd(100).minor, 0, usd(60).minor, 10).balance).toBe(0);
  });

  it("lets the balance GROW when the payment cannot cover the interest", () => {
    const r = accrue(usd(1000).minor, 0.24, usd(5).minor, 3);
    expect(r.balance).toBeGreaterThan(usd(1000).minor);
  });
});

describe("A BALANCE TRANSFER DOES NOT REDUCE DEBT", () => {
  it("adds the fee TO the balance — you owe more the moment it lands", () => {
    // $5,000 at 3% is $5,150 on day one. The marketing never contains this sentence.
    const a = assessTransfer(source(), offer(), { monthlyPayment: usd(300) });
    expect(a.moved.minor).toBe(usd(5000).minor);
    expect(a.fee.minor).toBe(usd(150).minor);
    expect(a.openingBalance.minor).toBe(usd(5150).minor);
  });

  it("leaves you owing exactly the fee more than before", () => {
    const s = source();
    const a = assessTransfer(s, offer(), { monthlyPayment: usd(300) });
    expect(debtAfterTransfer(s, a).minor).toBe(s.owed!.minor + a.fee.minor);
    // It is not a saving, it is a purchase: a lower rate for a window, priced whether or not the
    // window is used well.
    expect(debtAfterTransfer(s, a).minor).toBeGreaterThan(s.owed!.minor);
  });

  it("honours a fee FLOOR on a small transfer", () => {
    const a = assessTransfer(source({ owed: usd(200) }), offer({ transferFeeMin: usd(10) }), {
      monthlyPayment: usd(100),
    });
    expect(a.fee.minor).toBe(usd(10).minor);
  });
});

describe("the saving is measured against what you would ACTUALLY pay", () => {
  it("compares both sides at the SAME payment", () => {
    // Otherwise the answer measures a change of behaviour rather than the offer.
    const a = assessTransfer(source(), offer(), { monthlyPayment: usd(300) });
    expect(a.interestWith.minor).toBe(0);
    expect(a.interestWithout.minor).toBeGreaterThan(0);
    expect(a.interestAvoided.minor).toBe(a.interestWithout.minor - a.interestWith.minor);
    expect(a.netBenefit.minor).toBe(a.interestAvoided.minor - a.fee.minor);
    expect(a.worthIt).toBe(true);
  });

  it("saves almost nothing when the debt would have cleared quickly anyway", () => {
    // An eighteen-month promotion on a balance you would have gone through in ONE month buys one
    // month of interest — about $21 — and charges $30 for it. The fee is priced against the length
    // of the promotion; the saving is priced against how long you would actually have carried it,
    // and only the second of those depends on you.
    const quick = assessTransfer(source({ owed: usd(1000) }), offer(), { monthlyPayment: usd(1000) });
    expect(quick.interestWithout.minor).toBeLessThan(quick.fee.minor);
    expect(quick.netBenefit.minor).toBeLessThan(0);
    expect(quick.worthIt).toBe(false);
    expect(quick.warnings.join(" ")).toContain("loses money");
  });

  it("calls a losing move a loss instead of reporting a smaller win", () => {
    const bad = assessTransfer(source({ apr: 0.05 }), offer({ transferFeeRate: 0.05 }), {
      monthlyPayment: usd(300),
    });
    expect(bad.netBenefit.minor).toBeLessThan(0);
    expect(bad.worthIt).toBe(false);
  });

  it("treats an unknown source rate as 0% and says the saving is a FLOOR", () => {
    const a = assessTransfer(source({ apr: undefined }), offer(), { monthlyPayment: usd(300) });
    expect(a.interestWithout.minor).toBe(0);
    expect(a.warnings.join(" ")).toContain("FLOOR");
  });
});

describe("the ways the bet is lost", () => {
  it("says when the go-to rate is WORSE than the rate being escaped", () => {
    const a = assessTransfer(source({ apr: 0.1999 }), offer({ goToApr: 0.2999 }), { monthlyPayment: usd(300) });
    expect(a.warnings.join(" ")).toContain("29.99% is HIGHER than the 19.99%");
  });

  it("says what is still owed when the promotion ends, and what that then costs", () => {
    const a = assessTransfer(source(), offer({ promoMonths: 12 }), { monthlyPayment: usd(200) });
    expect(a.balanceAtPromoEnd.minor).toBe(usd(5150 - 2400).minor);
    expect(a.costOfNotFinishing.minor).toBe(Math.round(a.balanceAtPromoEnd.minor * 0.2299));
    expect(a.warnings.join(" ")).toContain("at once, not gradually");
  });

  it("gives the payment that actually clears it inside the window, rounded UP", () => {
    // A payment a cent short leaves a balance to revert, so this rounds up rather than to nearest.
    const a = assessTransfer(source(), offer({ promoMonths: 18 }), { monthlyPayment: usd(200) });
    expect(a.requiredMonthly.minor).toBe(Math.ceil(usd(5150).minor / 18));
    const cleared = assessTransfer(source(), offer({ promoMonths: 18 }), {
      monthlyPayment: { ...a.requiredMonthly },
    });
    expect(cleared.balanceAtPromoEnd.minor).toBe(0);
  });

  it("calls a payment that cannot cover even the promotional interest a delay, not a plan", () => {
    const a = assessTransfer(source(), offer({ promoApr: 0.0499 }), { monthlyPayment: usd(5) });
    expect(a.warnings.join(" ")).toContain("it is a delay");
  });

  it("prices the worst case: a year of the go-to rate on the whole opening balance", () => {
    const o = offer();
    const a = assessTransfer(source(), o, { monthlyPayment: usd(300) });
    expect(worstCaseAnnual(a, o).minor).toBe(Math.round(usd(5150).minor * 0.2299));
  });
});

describe("the limit caps it, and filling a card has its own price", () => {
  it("moves only what fits, and says the rest stays where it is", () => {
    const a = assessTransfer(source({ owed: usd(9000) }), offer({ creditLimit: usd(5000) }), {
      monthlyPayment: usd(300),
    });
    expect(a.moved.minor).toBe(usd(5000).minor);
    expect(a.warnings.join(" ")).toContain("the plan has to cover both");
  });

  it("calls an unknown limit an ASSUMPTION rather than treating it as unlimited", () => {
    const a = assessTransfer(source(), offer({ creditLimit: undefined }), { monthlyPayment: usd(300) });
    expect(a.warnings.join(" ")).toContain("an assumption, not a fact");
  });

  it("names the cost of filling the new line that is not interest", () => {
    const a = assessTransfer(source(), offer({ creditLimit: usd(5500) }), { monthlyPayment: usd(300) });
    expect(a.warnings.join(" ")).toContain("94% of the new line");
    expect(a.warnings.join(" ")).toContain("not interest");
  });

  it("never moves more than is owed, however much room the offer has", () => {
    const a = assessTransfer(source({ owed: usd(500) }), offer({ creditLimit: usd(20_000) }), {
      monthlyPayment: usd(100),
    });
    expect(a.moved.minor).toBe(usd(500).minor);
  });
});

describe("rankTransfers", () => {
  const debts = [source(), source({ account: "b", institution: "Beta Card", owed: usd(800), apr: 0.1499 })];

  it("ranks by net benefit and KEEPS the losers, so a bad offer is visibly bad", () => {
    const out = rankTransfers(debts, [offer(), offer({ id: "greedy", transferFeeRate: 0.08 })], {
      monthlyPayment: usd(300),
    });
    expect(out).toHaveLength(4);
    for (let i = 1; i < out.length; i++) {
      expect(out[i].netBenefit.minor).toBeLessThanOrEqual(out[i - 1].netBenefit.minor);
    }
    expect(out.some((a) => !a.worthIt)).toBe(true);
  });

  it("will not transfer a balance onto the card it is already on", () => {
    const out = rankTransfers([source()], [offer({ institution: "Alpha Card" })], { monthlyPayment: usd(300) });
    expect(out).toEqual([]);
  });

  it("skips an account that owes nothing", () => {
    const clear = source({ account: "c", owed: undefined, balance: usd(0) });
    expect(rankTransfers([clear], [offer()], { monthlyPayment: usd(300) })).toEqual([]);
  });
});
